package me.xjanua.aitranswatch.repository;
import java.util.UUID; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import org.springframework.data.jpa.repository.JpaRepository; import me.xjanua.aitranswatch.enums.DriverStatus; import me.xjanua.aitranswatch.model.Driver;
public interface DriverRepository extends JpaRepository<Driver, UUID> { boolean existsByEmployeeCodeIgnoreCase(String employeeCode); boolean existsByLicenseNumberIgnoreCase(String licenseNumber); Page<Driver> findByStatus(DriverStatus status, Pageable pageable); Page<Driver> findByEmployeeCodeContainingIgnoreCaseOrLicenseNumberContainingIgnoreCase(String code,String license,Pageable pageable); Page<Driver> findByStatusAndEmployeeCodeContainingIgnoreCaseOrStatusAndLicenseNumberContainingIgnoreCase(DriverStatus s1,String code,DriverStatus s2,String license,Pageable pageable); }
